function (repo, pr) {
      var u = this.cur();
      var self = this;
      var canManage = this.canWrite(repo, u) && !!(u && (pr.author === u.id || rank(this.roleOn(repo, u)) >= 4));
      var reqs = list('reviewers').filter(function (r) { return r.pr === pr.id; }).map(function (r) {
        var a = userById(r.user);
        var name = a ? a.username : r.user;
        return '<span class="reviewer">' + esc(name) + '</span> ' +
          (canManage ? '<button type="button" data-action="remove-reviewer" data-id="' + esc(r.user) + '">Remove ' + esc(name) + '</button>' : '');
      }).join(' ');
      var prot = list('protections').find(function (p) { return p.repo === repo.id && p.branch === pr.base; });
      var ck = list('checks').filter(function (c) { return c.pr === pr.id && c.commit === pr.compareCommit; })[0];
      var approved = list('reviews').filter(function (r) {
        return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Approved' && r.reviewer !== pr.author;
      }).length;
      var changes = list('reviews').filter(function (r) {
        return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Changes requested';
      }).length;
      var ok = pr.status === 'open' && (!prot || !prot.approval || approved >= 1);
      var canMerge = rank(this.roleOn(repo, u)) >= 4;
      var mergeArea = '<h2>Merge</h2><p>Create a merge commit</p>' +
        (pr.status === 'merged' ? '<p>Merged</p>' : '') +
        (pr.status === 'closed' ? '<p>This pull request is closed.</p>' : '') +
        (pr.status === 'draft' ? '<p>Draft</p>' : '') +
        ((pr.status === 'open' || pr.status === 'draft') && canMerge
          ? (ok ? '<p><button type="button" data-action="merge-pr">Merge pull request</button></p>'
            : '<p><button type="button" disabled>Merge pull request</button></p>' + (changes || (prot && prot.approval && approved < 1)
              ? '<p>Review required by branch protection</p>' : '<p>This pull request cannot be merged yet.</p>'))
          : '') +
        (pr.status === 'open' || pr.status === 'draft' ? '' : '');
      var statusCtl = '';
      if (u && (pr.author === u.id || rank(this.roleOn(repo, u)) >= 4)) {
        if (pr.status === 'draft') statusCtl = '<p><button type="button" data-action="ready-for-review">Ready for review</button></p>';
        if (pr.status === 'open' || pr.status === 'draft') statusCtl += '<p><button type="button" data-action="close-pr">Close pull request</button></p>';
        else if (pr.status === 'closed') statusCtl = '<p><button type="button" data-action="reopen-pr">Reopen pull request</button></p>';
      }
      var canAdmin = rank(this.roleOn(repo, u)) >= 5;
      var checkHtml = '<h2>Checks</h2><p class="meta">test: ' + esc(ck ? ck.status : 'pending') + '</p>' +
        (ck && ck.setter ? '<p class="meta">Set by ' + esc((userById(ck.setter) || {}).username || '') + '</p>' : '') +
        (canAdmin
          ? '<p class="field"><label for="in-test-status">test status</label>' +
            '<select id="in-test-status" name="testStatus">' +
            ['pending', 'success', 'failure'].map(function (s) {
              return '<option value="' + s + '"' + ((ck ? ck.status : 'pending') === s ? ' selected' : '') + '>' + s + '</option>';
            }).join('') +
            '</select></p><p><button type="button" data-action="save-check">Save</button></p>'
          : '');
      var reviewHtml = list('reviews').filter(function (rv) { return rv.pr === pr.id; }).map(function (rv) {
        var ra = userById(rv.reviewer);
        return '<article class="card"><h3>' + esc(ra ? ra.username : '') + '</h3><p>' + esc(rv.state) + '</p>' +
          (rv.summary ? '<p>' + esc(rv.summary) + '</p>' : '') + '</article>';
      }).join('');
      return '<h2>Reviewers</h2>' +
        (canManage ? '<p><button type="button" data-action="reviewers-menu">Reviewers</button></p>' : '') +
        '<p>' + (reqs || 'No reviewers requested.') + '</p>' +
        '<h2>Reviews</h2>' + (reviewHtml || '<p>No reviews yet.</p>') +
        checkHtml + mergeArea + statusCtl;
    }

{
    screens: {},
    actions: {},
    repoHref: repoHref,
    ownerNameOf: ownerNameOf,
    userById: userById,
    repoById: repoById,
    repoByPath: repoByPath,
    orgById: orgById,
    orgBySlug: orgBySlug,
    branchOf: branchOf,
    filesOn: filesOn,
    commitsOn: commitsOn,
    currentBranch: currentBranch,
    setCurrentBranch: setCurrentBranch,
    timeAgo: timeAgo,

    /* ---------------------------------------------------------------- identity */
    cur: function () { return ARC.currentUser(); },
    isOrgOwner: function (orgId, u) {
      if (!u) return false;
      return list('memberships').some(function (m) { return m.org === orgId && m.user === u.id && m.role === 'Owner'; });
    },
    isOrgMember: function (orgId, u) {
      if (!u) return false;
      return list('memberships').some(function (m) { return m.org === orgId && m.user === u.id; });
    },
    roleOn: function (repo, u) {
      if (!repo) return null;
      if (u) {
        if (repo.ownerType === 'user' && repo.owner === u.id) return 'Admin';
        if (repo.ownerType === 'org' && this.isOrgOwner(repo.owner, u)) return 'Admin';
      }
      var best = null;
      var self = this;
      if (u) {
        var direct = grantFor(repo.id, 'user', u.id);
        if (direct) best = direct.role;
        var myTeams = list('teamMembers').filter(function (t) { return t.user === u.id; }).map(function (t) { return t.team; });
        list('grants').forEach(function (g) {
          if (g.repo !== repo.id || g.subjectType !== 'team') return;
          if (myTeams.indexOf(g.subject) < 0) return;
          if (rank(g.role) > rank(best)) best = g.role;
        });
      }
      if (best) return best;
      if (repo.visibility === 'public') return 'Read';
      return null;
    },
    canRead: function (repo, u) { return !!this.roleOn(repo, u); },
    canWrite: function (repo, u) { return rank(this.roleOn(repo, u)) >= 3; },
    canTriage: function (repo, u) { return rank(this.roleOn(repo, u)) >= 2; },
    canAdmin: function (repo, u) { return rank(this.roleOn(repo, u)) >= 5; },
    visibleOrgs: function (u) {
      var self = this;
      return list('orgs').filter(function (o) {
        if (!u) return list('repos').some(function (r) { return r.owner === o.id && r.visibility === 'public'; });
        return self.isOrgMember(o.id, u);
      });
    },
    readRepos: function (u) {
      var self = this;
      return list('repos').filter(function (r) { return self.canRead(r, u); });
    },

    /* ---------------------------------------------------------------- layout bits */
    accountBar: function (user) {
      var q = ui().search || '';
      var search = '<form class="global-search" data-action="global-search">' +
        '<input type="text" role="searchbox" aria-label="Search" placeholder="Search" name="q" value="' + esc(q) + '">' +
        '</form>';
      if (!user) return search + '<a href="#/signin">Sign in</a> <a href="#/signup">Sign up</a>';
      return search +
        '<button type="button" data-action="account-menu" aria-haspopup="true">Account menu</button>' +
        '<span class="username">' + esc(user.username) + '</span>';
    },

    input: function (label, name, opts) {
      opts = opts || {};
      var id = 'in-' + String(name).replace(/[^A-Za-z0-9_-]/g, '_');
      return '<p class="field"><label for="' + id + '">' + esc(label) + '</label>' +
        '<input id="' + id + '" type="' + (opts.type || 'text') + '" name="' + esc(name) + '" ' +
        'placeholder="' + esc(opts.placeholder || label) + '"' +
        (opts.value != null ? ' value="' + esc(opts.value) + '"' : '') + '></p>';
    },
    textarea: function (label, name, value) {
      var id = 'in-' + String(name).replace(/[^A-Za-z0-9_-]/g, '_');
      return '<p class="field"><label for="' + id + '">' + esc(label) + '</label>' +
        '<textarea id="' + id + '" name="' + esc(name) + '" aria-label="' + esc(label) + '" placeholder="' + esc(label) + '">' + esc(value || '') + '</textarea></p>';
    },
    errorBox: function (key) {
      var e = ui().errors || {};
      return e[key] ? '<p class="field-error" role="alert">' + esc(e[key]) + '</p>' : '';
    },
    alert: function (msg) { return '<p class="alert" role="alert">' + esc(msg) + '</p>'; },
    denied: function () {
      return '<h1>Access denied</h1><p>Access denied. <a href="#/signin">Sign in</a> to continue.</p>';
    },
    notFound: function () { return '<h1>Not found</h1><p>This page does not exist.</p>'; },

    /* ---------------------------------------------------------------- home */
    home: function () {
      var u = this.cur();
      var self = this;
      var repos = this.readRepos(u);
      var orgs = this.visibleOrgs(u);
      var orgCards = orgs.map(function (o) {
        return '<article class="card"><h3><a href="#/orgs/' + encodeURIComponent(o.slug) + '">' + esc(o.name) + '</a></h3>' +
          '<p class="meta">Organization</p></article>';
      }).join('');
      var repoCards = repos.map(function (r) {
        return '<article class="card"><h3><a href="' + self.repoHref(r) + '">' + esc(r.name) + '</a></h3>' +
          '<p class="meta">' + esc(ownerNameOf(r) + '/' + r.name) + '</p>' +
          '<p class="meta"><span title="' + esc(r.visibility === 'public' ? 'Public' : 'Private') + '">' +
          esc(r.visibility === 'public' ? 'Public' : 'Private') + '</span> · updated ' + esc(timeAgo(r.updated)) + '</p>' +
          '<p>' + esc(r.description) + '</p></article>';
      }).join('');
      return '<h1>Home</h1>' +
        '<p>Welcome to the GitHub collaboration platform.</p>' +
        (u ? '<p><a href="#/repos/new">New repository</a>' + (function () {
          var writable = repos.filter(function (r) { return self.canWrite(r, u); })[0];
          return writable ? ' <a href="' + self.repoHref(writable, 'pulls') + '">Pull requests</a>' : '';
        })() + '</p>' : '<p><a href="#/forgot">Forgot password</a></p>') +
        '<h2>Organizations</h2>' + (orgCards || '<p>No organizations.</p>') +
        '<h2>Repositories</h2>' + (repoCards || '<p>No repositories.</p>');
    },
    dashboard: function () {
      var u = this.cur();
      if (!u) return '<h1>Dashboard</h1>' + this.denied();
      var self = this;
      var orgs = this.visibleOrgs(u);
      var repos = this.readRepos(u);
      return '<h1>Dashboard</h1>' +
        '<p>Signed in as <strong>' + esc(u.username) + '</strong>.</p>' +
        '<h2>Your organizations</h2>' +
        (orgs.map(function (o) {
          return '<article class="card"><h3><a href="#/orgs/' + encodeURIComponent(o.slug) + '">' + esc(o.name) + '</a></h3>' +
            '<p class="meta">' + esc(o.slug) + '</p></article>';
        }).join('') || '<p>No organizations yet.</p>') +
        '<h2>Your repositories</h2>' +
        (repos.map(function (r) {
          return '<article class="card"><h3><a href="' + self.repoHref(r) + '">' + esc(r.name) + '</a></h3>' +
            '<p class="meta">' + esc(ownerNameOf(r) + '/' + r.name) + '</p></article>';
        }).join('') || '<p>No repositories yet.</p>');
    },

    /* ---------------------------------------------------------------- account access */
    signinScreen: function () {
      var u = ui();
      return '<h1>Sign in</h1>' +
        '<form data-action="do-signin">' +
        this.input('Username or email', 'user', { value: u.signinUser || '' }) +
        this.input('Password', 'password', { type: 'password' }) +
        '<button type="submit">Sign in</button></form>' +
        '<p><a href="#/signup">Create an account</a></p>' +
        '<p><a href="#/forgot">Forgot password</a></p>';
    },
    signupScreen: function () {
      var u = ui();
      var v = u.signupValues || {};
      return '<h1>Create an account</h1>' +
        '<form data-action="do-signup">' +
        this.input('Username', 'username', { value: v.username || '' }) + this.errorBox('username') +
        this.input('Email', 'email', { value: v.email || '' }) + this.errorBox('email') +
        this.input('Password', 'password', { type: 'password' }) + this.errorBox('password') +
        this.input('Confirm password', 'confirm', { type: 'password' }) + this.errorBox('confirm') +
        '<p class="field"><label for="in-terms"><input id="in-terms" type="checkbox" name="terms">Agree to the terms</label></p>' +
        this.errorBox('terms') +
        '<button type="submit">Create account</button></form>' +
        '<p><a href="#/signin">Sign in</a></p>';
    },
    forgotScreen: function () {
      var u = ui();
      if (!u.resetEmail) {
        return '<h1>Forgot password</h1>' +
          '<form data-action="send-reset">' +
          this.input('Email', 'email', {}) +
          '<button type="submit">Send reset link</button></form>' +
          '<p><a href="#/signin">Sign in</a></p>';
      }
      return '<h1>Forgot password</h1>' +
        '<p>Verification code</p>' +
        '<p role="status">123456</p>' +
        '<form data-action="do-reset">' +
        this.input('Verification code', 'code', {}) + this.errorBox('code') +
        this.input('New password', 'password', { type: 'password' }) + this.errorBox('password') +
        this.input('Confirm password', 'confirm', { type: 'password' }) + this.errorBox('confirm') +
        '<button type="submit">Reset password</button></form>';
    },
    settingsScreen: function (route) {
      var u = this.cur();
      if (!u) return '<h1>Settings</h1>' + this.denied();
      if (route.params[0] === 'password') {
        return '<h1>Password and authentication</h1>' +
          '<form data-action="update-password">' +
          this.input('Current password', 'current', { type: 'password' }) + this.errorBox('current') +
          this.input('New password', 'next', { type: 'password' }) + this.errorBox('next') +
          this.input('Confirm password', 'confirm', { type: 'password' }) + this.errorBox('confirm') +
          '<button type="submit">Update password</button></form>' +
          '<p><a href="#/settings">Settings</a></p>';
      }
      return '<h1>Settings</h1>' +
        '<p>Signed in as <strong>' + esc(u.username) + '</strong>.</p>' +
        '<h2>Password and authentication</h2>' +
        '<p><a href="#/settings/password">Password and authentication</a></p>';
    },

    /* ---------------------------------------------------------------- organizations */
    orgsScreen: function (route) {
      var p = route.params;
      if (p[0] === 'new') return this.newOrgScreen();
      if (!p.length) return this.orgListScreen();
      var org = orgBySlug(p[0]) || orgById(p[0]);
      if (!org) return this.notFound();
      if (p[1] === 'repositories') return this.orgReposScreen(org);
      if (p[1] === 'people') return this.orgPeopleScreen(org);
      if (p[1] === 'teams') {
        if (p[2] === 'new') return this.newTeamScreen(org);
        if (!p[2]) return this.orgTeamsScreen(org);
        var team = list('teams').find(function (t) { return t.org === org.id && t.name === p[2]; });
        if (!team) return this.notFound();
        if (p[3] === 'settings') return this.teamSettingsScreen(org, team);
        return this.teamMembersScreen(org, team);
      }
      return this.orgOverview(org);
    },
    orgHeader: function (org) {
      return '<h1>' + esc(org.name) + '</h1><p class="meta">' + esc(org.slug) + '</p>';
    },
    orgNav: function (org) {
      var base = '#/orgs/' + encodeURIComponent(org.slug);
      return '<nav class="subtabs">' +
        '<a href="' + base + '/repositories">Repositories</a> ' +
        '<a href="' + base + '/people">People</a> ' +
        '<a href="' + base + '/teams">Teams</a></nav>';
    },
    orgOverview: function (org) {
      return this.orgHeader(org) + this.orgNav(org) + '<p>' + esc(org.display) + '</p>';
    },
    orgListScreen: function () {
