    },
    orgReposScreen: function (org) {
      var self = this;
      var u = this.cur();
      var f = ui().orgRepoFilter || { q: '', visibility: 'all' };
      var repos = list('repos').filter(function (r) { return r.owner === org.id && self.canRead(r, u); });
      var rows = repos.filter(function (r) {
        if (f.q && r.name.toLowerCase().indexOf(String(f.q).toLowerCase()) < 0) return false;
        if (f.visibility !== 'all' && r.visibility !== f.visibility) return false;
        return true;
      }).map(function (r) {
        return '<article class="card" data-repo="' + esc(r.id) + '">' +
