        '<p>' +
        '<button type="button" data-action="org-visibility" data-value="all">All</button> ' +
        '<button type="button" data-action="org-visibility" data-value="public">Public</button> ' +
        '<button type="button" data-action="org-visibility" data-value="private">Private</button></p>' +
        '<div id="org-repo-rows">' + (rows || '<p>No repositories.</p>') + '</div>';
    },
    orgRepoRows: function (org) {
      var self = this;
      var u = this.cur();
      var f = ui().orgRepoFilter || { q: '', visibility: 'all' };
      var repos = list('repos').filter(function (r) { return r.owner === org.id && self.canRead(r, u); });
      var rows = repos.filter(function (r) {
        if (f.q && r.name.toLowerCase().indexOf(String(f.q).toLowerCase()) < 0) return false;
        if (f.visibility !== 'all' && r.visibility !== f.visibility) return false;
        return true;
      }).map(function (r) {
        return '<article class="card" data-repo="' + esc(r.id) + '">' +
          '<h3><a href="' + self.repoHref(r) + '">' + esc(r.name) + '</a></h3>' +
          '<p class="meta">' + esc(ownerNameOf(r) + '/' + r.name) + '</p>' +
          '<p class="meta"><span title="' + esc(r.visibility === 'public' ? 'Public' : 'Private') + '">' +
          esc(r.visibility === 'public' ? 'Public' : 'Private') + '</span></p>' +
          '<p>' + esc(r.description) + '</p>' +
          '<p class="meta">updated ' + esc(timeAgo(r.updated)) + '</p></article>';
      }).join('');
      return rows || '<p>No repositories.</p>';
    },
    orgPeopleScreen: function (org) {
      var self = this;
      var u = this.cur();
      var owner = this.isOrgOwner(org.id, u);
      var rows = list('memberships').filter(function (m) { return m.org === org.id; }).map(function (m) {
        var acc = userById(m.user);
