        '</select></p>' +
        '<button type="submit">Create team</button></form>';
    },
    orgTeamsScreen: function (org) {
      var u = this.cur();
      var owner = this.isOrgOwner(org.id, u);
      var base = '#/orgs/' + encodeURIComponent(org.slug) + '/teams';
      var rows = list('teams').filter(function (t) { return t.org === org.id; }).map(function (t) {
