    teamHeader: function (org, team) {
      return '<h1>' + esc(org.name + '/' + team.name) + '</h1>';
    },
    teamNav: function (org, team) {
      var base = '#/orgs/' + encodeURIComponent(org.slug) + '/teams/' + encodeURIComponent(team.name);
      return '<nav class="subtabs"><a href="' + base + '">Members</a> <a href="' + base + '/settings">Settings</a></nav>';
    },
    teamMembersScreen: function (org, team) {
      var self = this;
      var u = this.cur();
      var owner = this.isOrgOwner(org.id, u);
      var members = list('teamMembers').filter(function (m) { return m.team === team.id; });
      var rows = members.map(function (m) {
        var acc = userById(m.user);
        var name = acc ? acc.username : m.user;
        return '<article class="card" data-member="' + esc(m.user) + '"><h3>' + esc(name) + '</h3>' +
          (owner ? '<p><button type="button" data-action="remove-team-member" data-id="' + esc(m.user) + '">Remove ' + esc(name) + '</button></p>' : '') + '</article>';
      }).join('');
      var form = owner ? '<p><button type="button" data-action="add-team-member-open">Add member</button></p>' : '';
      return this.teamHeader(org, team) + this.teamNav(org, team) + '<h2>Members</h2>' + form +
        (rows || '<p>No team members.</p>') +
        this.teamTree(org, team);
    },
    teamTree: function (org, team) {
      var parent = team.parent ? list('teams').find(function (t) { return t.id === team.parent; }) : null;
      var children = list('teams').filter(function (t) { return t.parent === team.id; });
      return '<h2>Team tree</h2><p>Organization: ' + esc(org.name) + '</p>' +
        '<p>Parent team: ' + esc(parent ? parent.name : 'None') + '</p>' +
        '<p>Child teams: ' + esc(children.map(function (c) { return c.name; }).join(', ') || 'None') + '</p>';
    },
    teamSettingsScreen: function (org, team) {
      var u = this.cur();
      if (!this.isOrgOwner(org.id, u)) return this.teamHeader(org, team) + this.denied();
      var options = list('teams').filter(function (t) { return t.org === org.id && t.id !== team.id; });
      return this.teamHeader(org, team) + this.teamNav(org, team) +
        '<h2>Settings</h2>' + this.errorBox('parent') +
        '<form data-action="save-team-parent">' +
        '<p class="field"><label for="in-parent-team">Parent team</label><select id="in-parent-team" name="parent"><option value="">None</option>' +
        options.map(function (t) {
          return '<option value="' + esc(t.id) + '"' + (team.parent === t.id ? ' selected' : '') + '>' + esc(t.name) + '</option>';
        }).join('') +
        '</select></p>' +
        '<button type="submit">Save</button></form>' + this.teamTree(org, team);
    },

    /* ---------------------------------------------------------------- repositories */
    reposScreen: function (route) {
      var p = route.params;
      if (p[0] === 'new') return this.newRepoScreen();
      var repo = repoByPath(p[0], p[1]);
      if (!repo) return this.notFound();
      if (!this.canRead(repo, this.cur())) return this.denied();
      var section = p[2];
      if (section === 'code') return this.codeScreen(repo, p[3] || currentBranch(repo), p.slice(4));
      if (section === 'commits') return this.commitsScreen(repo, p[3] || currentBranch(repo), p.slice(4));
      if (section === 'commit') return this.commitScreen(repo, p[3]);
      if (section === 'compare') return this.compareScreen(repo, p[3]);
      if (section === 'issues') {
        if (p[3] === 'new') return this.newIssueScreen(repo);
        if (p[3]) return this.issueDetailScreen(repo, Number(p[3]));
        return this.issueListScreen(repo);
      }
      if (section === 'pulls') {
        if (p[3]) return this.pullDetailScreen(repo, Number(p[3]), p[4]);
        return this.pullListScreen(repo);
      }
      if (section === 'settings') {
        if (p[3] === 'general') return this.repoGeneralScreen(repo);
        if (p[3] === 'branches') return this.repoBranchesScreen(repo);
        if (p[3] === 'access') return this.repoAccessScreen(repo);
        return this.repoSettingsIndex(repo);
      }
      return this.repoOverview(repo);
    },
    repoTitle: function (repo) { return ownerNameOf(repo) + '/' + repo.name; },
    repoHeader: function (repo, branch, omitCommits) {
      var u = this.cur();
      var canWrite = this.canWrite(repo, u);
      var vis = repo.visibility === 'public' ? 'Public' : 'Private';
      var b = branch || currentBranch(repo);
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1>' +
        '<p><span class="marker" title="' + esc(vis) + '">' + esc(vis) + '</span></p>' +
        '<p>' + esc(repo.description) + '</p>' +
        '<nav class="subtabs">' +
        '<a href="' + repoHref(repo) + '/code/' + encodeURIComponent(b) + '">Code</a> ' +
        '<a href="' + repoHref(repo) + '/issues">Issues</a> ' +
        '<a href="' + repoHref(repo) + '/pulls">Pull requests</a> ' +
        '<a href="' + repoHref(repo) + '/settings">Settings</a></nav>' +
        '<p>' +
        '<button type="button" data-action="clone-menu">Code</button> ' +
        '<span class="branch-wrap"><button type="button" data-action="branch-menu">Branch ' + esc(b) + '</button></span> ' +
        (omitCommits ? '' : '<a href="' + repoHref(repo) + '/commits/' + encodeURIComponent(b) + '">Commits</a> <span class="count">' + commitsOn(repo.id, b).length + '</span> ') +
        (canWrite ? '<button type="button" data-action="add-file-menu">Add file</button>' : '') +
        '</p>';
    },
    repoOverview: function (repo) {
      return this.repoHeader(repo) + this.fileBrowser(repo, currentBranch(repo), []) +
        (repo.forkOf
          ? '<p>Forked from <a href="' + repoHref(repoById(repo.forkOf) || repo) + '">' + esc((repoById(repo.forkOf) || {}).name || '') + '</a></p>'
          : '') +
        (this.cur() ? '<p><button type="button" data-action="fork-open">Fork</button></p>' : '');
    },
    fileBrowser: function (repo, branch, pathParts) {
      pathParts = pathParts || [];
      var all = filesOn(repo.id, branch);
      var prefix = pathParts.join('/');
      if (prefix) {
        var open = all.find(function (f) { return f.path === prefix; });
        if (open) {
          return this.fileCrumbs(repo, branch, pathParts) +
            '<h2>' + esc(open.path) + '</h2>' +
            '<p class="meta">Branch ' + esc(branch) + '</p>' +
            '<p><button type="button" data-action="edit-file" data-path="' + esc(open.path) + '">Edit</button></p>' +
            '<pre class="file-content">' + highlight(open.content, ui().search) + '</pre>';
        }
      }
      var names = {};
      all.forEach(function (f) {
        if (prefix && f.path.indexOf(prefix + '/') !== 0) return;
        var rest = prefix ? f.path.slice(prefix.length + 1) : f.path;
        if (!rest) return;
        var seg = rest.split('/')[0];
        names[seg] = rest.indexOf('/') >= 0;
      });
      var base = repoHref(repo) + '/code/' + encodeURIComponent(branch) + (prefix ? '/' + prefix.split('/').map(encodeURIComponent).join('/') : '');
      var rows = Object.keys(names).sort(function (a, b) { return names[b] - names[a] || a.localeCompare(b); }).map(function (n) {
        return '<li><a href="' + base + '/' + encodeURIComponent(n) + '">' + esc(n) + '</a></li>';
      }).join('');
      return this.fileCrumbs(repo, branch, pathParts) + '<h2>Files</h2><ul class="file-list">' + (rows || '<li>No files on this branch.</li>') + '</ul>';
    },
    fileCrumbs: function (repo, branch, pathParts) {
      pathParts = pathParts || [];
      return '<p class="breadcrumbs"><a href="' + repoHref(repo) + '/code/' + encodeURIComponent(branch) + '">' + esc(repo.name) + '</a>' +
        pathParts.map(function (part, i) {
          var up = pathParts.slice(0, i + 1).map(encodeURIComponent).join('/');
          return ' / <a href="' + repoHref(repo) + '/code/' + encodeURIComponent(branch) + '/' + up + '">' + esc(part) + '</a>';
        }).join('') + '</p>';
    },
    codeScreen: function (repo, branch, pathParts) {
      if (!branchOf(repo.id, branch)) return this.notFound();
      var path = pathParts ? pathParts.join('/') : '';
      return this.repoHeader(repo, branch) + this.fileBrowser(repo, branch, pathParts || []);
    },
    commitsScreen: function (repo, branch, pathParts) {
      var path = pathParts ? pathParts.join('/') : '';
      var all = commitsOn(repo.id, branch).slice().sort(function (a, b) { return Date.parse(b.time) - Date.parse(a.time); });
      var shown = path ? all.filter(function (c) { return (c.changes || []).some(function (ch) { return ch.path === path; }); }) : all;
      var rows = shown.map(function (c) {
        return '<article class="card"><h3><a href="' + repoHref(repo) + '/commit/' + encodeURIComponent(c.id) + '">' +
          esc(c.id.replace(/^c-/, '')) + '</a> <a href="' + repoHref(repo) + '/commit/' + encodeURIComponent(c.id) + '">' + esc(c.message) + '</a></h3>' +
          '<p class="meta">' + esc(userById(c.author) ? userById(c.author).username : '') + ' · ' + esc(timeAgo(c.time)) + '</p>' +
          '<p class="meta">' + (c.changes || []).map(function (ch) { return esc(ch.path); }).join(', ') + '</p></article>';
      }).join('');
      return this.repoHeader(repo, branch) + '<h2>Commits</h2>' + (path ? '<p>Commits for ' + esc(path) + '</p>' : '') +
        (rows || '<p>No commits for this scope.</p>');
    },
    commitScreen: function (repo, id) {
      var c = list('commits').find(function (x) { return x.id === id && x.repo === repo.id; });
      if (!c) return this.notFound();
      var add = (c.changes || []).reduce(function (n, ch) { return n + (ch.additions || 0); }, 0);
      var del = (c.changes || []).reduce(function (n, ch) { return n + (ch.deletions || 0); }, 0);
      var rows = (c.changes || []).map(function (ch) {
        return '<article class="card"><h3>' + esc(ch.path) + '</h3>' +
          '<p class="meta">+' + ch.additions + ' −' + ch.deletions + '</p></article>';
      }).join('');
      return this.repoHeader(repo, c.branch) +
        '<h1>' + esc(c.message) + '</h1>' +
        '<p class="meta">' + esc(userById(c.author) ? userById(c.author).username : '') + ' · ' + esc(timeAgo(c.time)) + '</p>' +
        '<p class="meta">Parent: ' + esc(c.parent || 'None') + '</p>' +
        '<h2>Changed files</h2>' + rows +
        '<p>' + add + ' additions, ' + del + ' deletions</p>';
    },
    compareScreen: function (repo, second) {
      var u = this.cur();
      if (!this.canWrite(repo, u)) return this.denied();
      var branches = list('branches').filter(function (b) { return b.repo === repo.id; }).map(function (b) { return b.name; });
      var st = ui().compare || {};
      var base = st.base || repo.default;
      var compare = st.compare || second || (branches.find(function (b) { return b !== base; }) || base);
      var same = base === compare;
      var changed = same ? [] : this.branchDiff(repo, base, compare);
      var opts = function (sel) {
        return branches.map(function (b) { return '<option value="' + esc(b) + '"' + (b === sel ? ' selected' : '') + '>' + esc(b) + '</option>'; }).join('');
      };
      var summary = same ? '<p>No changes</p>' : '<p>' + changed.length + ' changed files</p>' +
        '<p>Commit summary</p><p>' + commitsOn(repo.id, compare).length + ' comparable commits</p>' +
        '<h2>Changed files</h2>' + changed.map(function (ch) {
          return '<article class="card"><h3>' + esc(ch.path) + '</h3><p class="meta">+' + ch.additions + ' −' + ch.deletions + '</p></article>';
        }).join('');
      var form = ui().prCreating ? this.prCreateForm(repo, base, compare) : '';
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1>' +
        '<h2>Compare changes</h2>' +
        '<p class="field"><label for="in-base">base</label><select id="in-base" name="base" data-change="compare-base">' + opts(base) + '</select></p>' +
        '<p class="field"><label for="in-compare">compare</label><select id="in-compare" name="compare" data-change="compare-compare">' + opts(compare) + '</select></p>' +
        '<p><button type="button" data-action="compare-changes">Compare changes</button></p>' +
        summary +
        (ui().prCreating ? '' : '<p><button type="button" data-action="create-pr-open"' + (same ? ' disabled' : '') + '>Create pull request</button> ' +
          '<button type="button" data-action="create-draft-open"' + (same ? ' disabled' : '') + '>Create draft pull request</button></p>') +
        form;
    },
    branchDiff: function (repo, base, compare) {
      var a = filesOn(repo.id, base);
      var b = filesOn(repo.id, compare);
      var out = [];
      b.forEach(function (f) {
        var other = a.find(function (x) { return x.path === f.path; });
        if (!other) out.push({ path: f.path, additions: f.content.split('\n').length - 1, deletions: 0 });
        else if (other.content !== f.content) out.push({ path: f.path, additions: f.content.split('\n').length - 1, deletions: other.content.split('\n').length - 1 });
      });
      return out;
    },
    prCreateForm: function (repo, base, compare) {
      var draft = !!ui().prDraft;
      return '<h2>' + (draft ? 'Create draft pull request' : 'Create pull request') + '</h2>' +
        '<form data-action="create-pr">' +
        '<p class="meta">base ' + esc(base) + ' ← compare ' + esc(compare) + '</p>' +
        this.input('Title', 'title', {}) + this.errorBox('title') +
        this.textarea('Description', 'body', '') +
        '<button type="submit">' + (draft ? 'Create draft pull request' : 'Create pull request') + '</button></form>';
    },
    repoSettingsIndex: function (repo) {
      var base = repoHref(repo) + '/settings';
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1><h2>Settings</h2>' +
        '<p><a href="' + base + '/general">General</a></p>' +
        '<p><a href="' + base + '/branches">Branches</a></p>' +
        '<p><a href="' + base + '/access">Manage access</a></p>';
    },
    repoGeneralScreen: function (repo) {
      var canAdmin = this.canAdmin(repo, this.cur());
      var base = repoHref(repo) + '/settings';
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1>' +
        '<p><a href="' + base + '">Settings</a></p>' +
        '<h2>General</h2>' +
        '<p>Visibility: <span class="marker" title="' + esc(repo.visibility === 'public' ? 'Public' : 'Private') + '">' + esc(repo.visibility === 'public' ? 'Public' : 'Private') + '</span></p>' +
        '<h2>Danger Zone</h2>' +
        (canAdmin ? '<p><button type="button" data-action="change-visibility">Change visibility</button></p>'
          : '<p>Visibility changes require repository Admin permission.</p>');
    },
    repoBranchesScreen: function (repo) {
      var u = this.cur();
      var canAdmin = this.canAdmin(repo, u);
      var base = repoHref(repo) + '/settings';
      var branches = list('branches').filter(function (b) { return b.repo === repo.id; });
      var rules = list('protections').filter(function (p) { return p.repo === repo.id; });
      var ruleHtml = rules.map(function (p) {
        return '<article class="card"><h3>' + esc(p.branch) + '</h3>' +
          '<p class="meta"><span>' + (p.approval ? '1 approval' : '') + '</span> ' +
          '<span>' + (p.check ? 'Require status check test' : '') + '</span></p></article>';
      }).join('');
      var maker = canAdmin ? '<p><button type="button" data-action="add-rule-open">Add branch protection rule</button></p>' : '';
      var def = canAdmin
        ? '<h2>Default branch</h2><form data-action="default-branch">' +
          '<p class="field"><label for="in-default">Default branch</label><select id="in-default" name="branch">' +
          branches.map(function (b) { return '<option value="' + esc(b.name) + '"' + (b.name === repo.default ? ' selected' : '') + '>' + esc(b.name) + '</option>'; }).join('') +
          '</select></p><button type="submit">Update</button></form>'
        : '<h2>Default branch</h2><p>Current default branch: ' + esc(repo.default) + '</p>';
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1>' +
        '<p><a href="' + base + '">Settings</a></p>' +
        '<h2>Branches</h2>' + maker + ruleHtml + def;
    },
    repoAccessScreen: function (repo) {
      var self = this;
      var canAdmin = this.canAdmin(repo, this.cur());
      if (!canAdmin) return this.denied();
      var subjects = [];
      list('grants').filter(function (g) { return g.repo === repo.id; }).forEach(function (g) {
        var name = g.subjectType === 'team'
          ? (list('teams').find(function (t) { return t.id === g.subject; }) || {}).name
          : (userById(g.subject) || {}).username;
        subjects.push({ grant: g, name: name });
      });
      var active = ui().activeGrant;
      var rows = subjects.map(function (s, index) {
        var isActive = active ? s.grant.id === active : index === 0;
        if (!isActive) {
          return '<article class="card" data-grant="' + esc(s.grant.id) + '"><h3>' + esc(s.name || s.grant.subject) + '</h3>' +
            '<p class="meta">' + esc(s.grant.role) + '</p></article>';
        }
        var options = ['Read', 'Triage', 'Write', 'Maintain', 'Admin'].map(function (r) {
          return '<option value="' + r + '"' + (r === s.grant.role ? ' selected' : '') + '>' + r + '</option>';
        }).join('');
        return '<article class="card" data-grant="' + esc(s.grant.id) + '"><h3>' + esc(s.name || s.grant.subject) + '</h3>' +
          '<p class="field"><label for="role-' + esc(s.grant.id) + '">Role</label><select id="role-' + esc(s.grant.id) + '" data-change="grant-role" data-id="' + esc(s.grant.id) + '">' + options + '</select></p>' +
          '<p><button type="button" data-action="save-grant" data-id="' + esc(s.grant.id) + '">Save</button></p></article>';
      }).join('');
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1>' +
        '<p><a href="' + repoHref(repo) + '/settings">Settings</a></p>' +
        '<h2>Manage access</h2>' +
        '<p><button type="button" data-action="add-access-open">Add people or teams</button></p>' +
        (rows || '<p>No direct access grants.</p>');
    },

    /* ---------------------------------------------------------------- issues */
    issueListScreen: function (repo) {
      var f = ui().issueFilter || {};
      var status = f.status || 'all';
      var q = f.q || '';
      var label = f.label || '';
      var rows = list('issues').filter(function (i) { return i.repo === repo.id; }).filter(function (i) {
        if (status !== 'all' && i.status !== status) return false;
        if (q && i.title.toLowerCase().indexOf(String(q).toLowerCase()) < 0 && String(i.body).toLowerCase().indexOf(String(q).toLowerCase()) < 0) return false;
        if (label && (i.labels || []).indexOf(label) < 0) return false;
        return true;
      }).map(function (i) { return this.issueRow(i); }, this).join('');
      var labels = list('labels').filter(function (l) { return l.repo === repo.id; }).map(function (l) {
        return '<a href="#" data-action="issue-label-filter" data-id="' + esc(l.id) + '">' + esc(l.name) + '</a>';
      }).join(' ');
      return this.repoHeader(repo) + '<h2>Issues</h2>' +
        '<p><a href="#" data-action="issue-status" data-value="open">Open</a> ' +
        '<a href="#" data-action="issue-status" data-value="closed">Closed</a></p>' +
        '<p><input type="search" aria-label="Search issues" placeholder="Search issues" data-change="issue-search" value="' + esc(q) + '"></p>' +
        '<p>' + labels + '</p>' +
        (this.canWrite(repo, this.cur()) ? '<p><a href="' + repoHref(repo) + '/issues/new">New issue</a></p>' : '') +
        '<div id="issue-rows">' + (rows || '<p>No issues match.</p>') + '</div>';
    },
    issueRow: function (i) {
      var repo = repoById(i.repo);
      var labels = (i.labels || []).map(function (id) {
        var l = list('labels').find(function (x) { return x.id === id; });
        return l ? '<span class="label-badge">' + esc(l.name) + '</span>' : '';
      }).join(' ');
      return '<article class="card" data-issue="' + esc(i.id) + '">' +
        '<h3><a href="' + repoHref(repo) + '/issues/' + i.number + '">' + esc(i.number) + '</a> ' +
        '<a href="' + repoHref(repo) + '/issues/' + i.number + '">' + esc(i.title) + '</a></h3>' +
        '<p class="meta"><span title="' + esc(i.status === 'open' ? 'Open' : 'Closed') + '">' + esc(i.status === 'open' ? 'Open' : 'Closed') + '</span> · ' +
        esc(userById(i.author) ? userById(i.author).username : '') + ' · updated ' + esc(timeAgo(i.updated)) + '</p>' +
        '<p class="meta">' + labels + '</p></article>';
    },
    newIssueScreen: function (repo) {
      if (!this.canWrite(repo, this.cur())) return this.denied();
      return '<h1>' + esc(this.repoTitle(repo)) + '</h1><h2>New issue</h2>' +
        '<form data-action="create-issue">' +
        this.input('Title', 'title', {}) + this.errorBox('title') +
        this.textarea('Description', 'body', '') +
        '<button type="submit">Submit new issue</button></form>';
    },
    issueDetailScreen: function (repo, number) {
      var i = list('issues').find(function (x) { return x.repo === repo.id && x.number === number; });
      if (!i) return this.notFound();
      var u = this.cur();
      var self = this;
      var writable = this.canWrite(repo, u);
      var triage = this.canTriage(repo, u);
      var pick = (ui().picker && ui().picker.issue === i.id) ? ui().picker.kind : null;
      var labels = (i.labels || []).map(function (id) {
        var l = list('labels').find(function (x) { return x.id === id; });
        return l ? '<span class="label-badge">' + esc(l.name) + '</span>' : '';
      }).join(' ');
      var assignees = (i.assignees || []).map(function (id) {
        var a = userById(id);
        return a ? esc(a.username) : '';
      }).join(', ');
      var ms = i.milestone ? (list('milestones').find(function (m) { return m.id === i.milestone; }) || {}).title : '';
      var comments = list('issueComments').filter(function (c) { return c.issue === i.id; }).map(function (c) {
        var author = userById(c.author);
        return '<article class="card" data-comment="' + esc(c.id) + '"><h3>' + esc(author ? author.username : '') + '</h3>' +
          '<p>' + esc(c.body) + '</p><p class="meta">' + esc(timeAgo(c.created)) + '</p>' +
          '<p><button type="button" data-action="reaction-menu" data-id="' + esc(c.id) + '">Add reaction</button> ' +
          self.reactionCount('comment', c.id) + '</p></article>';
      }).join('');
      var acts = list('activities').filter(function (a) { return a.kind === 'issue' && a.subject === i.id; }).map(function (a) {
        return '<article class="card"><p>' + esc(a.text) + '</p><p class="meta">' + esc(timeAgo(a.created)) + '</p></article>';
      }).join('');
      return this.repoHeader(repo) + '<h1>' + esc(i.title) + '</h1>' +
        '<p class="meta">#' + i.number + ' · <span title="' + esc(i.status === 'open' ? 'Open' : 'Closed') + '">' +
        esc(i.status === 'open' ? 'Open' : 'Closed') + '</span></p>' +
        (writable ? '<p><button type="button" data-action="edit-title-open">Edit issue title</button> ' +
          '<button type="button" data-action="edit-desc-open">Edit issue description</button></p>' : '') +
        '<p>' + esc(i.body) + '</p>' +
        '<h2>Assignees</h2><p>' + (assignees || 'No one assigned') + '</p>' +
        (triage ? '<p><button type="button" data-action="assignee-menu">Assignees</button></p>' + (pick === 'assignees' ? this.assigneePicker() : '') : '') +
        '<h2>Labels</h2><p>' + (labels || 'None yet') + '</p>' +
        (triage ? '<p><button type="button" data-action="label-menu">Labels</button></p>' : '') +
        '<h2>Milestone</h2><p>' + esc(ms || 'No milestone') + '</p>' +
        (triage ? '<p><button type="button" data-action="milestone-menu">Milestone</button></p>' + (pick === 'milestone' ? this.milestonePicker(repo, i) : '') : '') +
        (triage ? '<p><button type="button" data-action="toggle-issue">' + (i.status === 'open' ? 'Close issue' : 'Reopen issue') + '</button></p>' : '') +
