        '<nav class="subtabs">' +
        '<a href="' + base + '">Conversation</a> ' +
        '<a href="' + base + '/commits">Commits</a> ' +
        '<a href="' + base + '/files">Files changed</a> ' +
        '<a href="' + base + '/checks">Checks</a></nav>';
