function repoHref(repo, rest) {
    return '#/repos/' + encodeURIComponent(ownerSlugOf(repo)) + '/' + encodeURIComponent(repo.name) + (rest ? '/' + rest : '');
  }

function (route) {
    var name = route.name || 'home';
    if (name === 'home') return this.home();
    if (name === 'dashboard') return this.dashboard();
    if (name === 'signin') return this.signinScreen();
    if (name === 'signup') return this.signupScreen();
    if (name === 'forgot') return this.forgotScreen();
    if (name === 'settings') return this.settingsScreen(route);
    if (name === 'orgs') return this.orgsScreen(route);
    if (name === 'repos') return this.reposScreen(route);
    if (name === 'search') return this.searchScreen(route);
    return this.home();
  }

