    'do-signin': function (ctx) {
      var f = ctx.form || {};
      var id = String(f.user || '').trim();
      var pw = String(f.password || '');
      var found = list('users').find(function (u) {
        return (u.username === id || u.email === id) && u.password === pw;
      });
      ui().signinUser = id;
      if (!found) {
