      var errors = {};
      var code = String(f.code || '').trim();
      var pw = String(f.password || '');
      var cf = String(f.confirm || '');
      if (code !== '123456') errors.code = 'Verification code is invalid';
      var pwOk = pw.length >= 12 && pw.length <= 128 && /[A-Z]/.test(pw) && /[a-z]/.test(pw) && /[0-9]/.test(pw) &&
        /[^A-Za-z0-9]/.test(pw) && !/\s/.test(pw);
      if (!pwOk) errors.password = 'Password requirements are not satisfied';
      else if (cf !== pw) errors.confirm = 'Passwords do not match';
      ui().errors = errors;
      var email = ui().resetEmail;
      var acc = list('users').find(function (u) { return u.email === email; });
      if (Object.keys(errors).length) { ARC.render(); return; }
      ui().resetEmail = null;
      if (!acc) { ARC.render(); return; }
      acc.password = pw;
      ARC.save();
      ARC.render();
      ARC.notify('Password updated');
    },
    'update-password': function (ctx) {
      var u = this.cur ? this.cur() : ARC.currentUser();
      var f = ctx.form || {};
      var errors = {};
      var current = String(f.current || '');
      var next = String(f.next || '');
      var cf = String(f.confirm || '');
      if (!current) errors.current = 'Current password is required';
      else if (!u || current !== u.password) errors.current = 'Current password is incorrect';
      var pwOk = next.length >= 12 && next.length <= 128 && /[A-Z]/.test(next) && /[a-z]/.test(next) && /[0-9]/.test(next) &&
        /[^A-Za-z0-9]/.test(next) && !/\s/.test(next);
      if (!pwOk) errors.next = 'Password requirements are not satisfied';
      else if (cf !== next) errors.confirm = 'Password confirmation does not match';
      ui().errors = errors;
      if (Object.keys(errors).length) { ARC.render(); return; }
      u.password = next;
      ui().errors = {};
      ARC.save();
      ARC.render();
      ARC.notify('Password updated');
    },

