      if (members[idx].role === 'Owner' && owners.length <= 1) {
        ARC.notify('The last Owner cannot be removed');
        return;
      }
      members.splice(idx, 1);
      var tm = list('teamMembers');
      for (var i = tm.length - 1; i >= 0; i--) {
        var team = list('teams').find(function (t) { return t.id === tm[i].team; });
        if (team && team.org === org.id && tm[i].user === ctx.id) tm.splice(i, 1);
      }
      var gs = list('grants');
      for (var j = gs.length - 1; j >= 0; j--) {
        var repo = repoById(gs[j].repo);
