    'save-team-parent': function (ctx) {
      var r = ARC.route();
      var org = orgBySlug(r.params[0]);
      var team = list('teams').find(function (t) { return t.org === org.id && t.name === r.params[2]; });
      var parentId = String((ctx.form && ctx.form.parent) || '');
      var cyclic = false;
      var cursor = parentId;
      while (cursor) {
        if (cursor === team.id) { cyclic = true; break; }
        var t = list('teams').find(function (x) { return x.id === cursor; });
        cursor = t ? t.parent : null;
      }
      if (cyclic) {
        ui().errors = { parent: 'Cyclic team hierarchy is not allowed' };
        ARC.render();
        return;
      }
      team.parent = parentId || null;
      ui().errors = {};
      ARC.save();
      ARC.render();
      ARC.notify('Team saved');
    },

    /* repository creation and fork */
    'create-repo': function (ctx) {
      var u = ARC.currentUser();
      var f = ctx.form || {};
      var name = String(f.name || '').trim();
      var owner = String(f.owner || '');
      var parts = owner.split(':');
      var errors = {};
      var ownerId = parts[1];
      var ownerType = parts[0];
      var exists = list('repos').some(function (r) { return r.name === name && r.owner === ownerId; });
      if (!name) errors.name = 'Repository name is required';
      else if (exists) errors.name = 'Repository name already exists';
      ui().errors = errors;
      ui().repoValues = { name: name, description: String(f.description || '') };
      if (Object.keys(errors).length) { ARC.render(); return; }
      var repo = {
        id: uid('r'), name: name, owner: ownerId, ownerType: ownerType,
        visibility: f.visibility === 'private' ? 'private' : 'public',
        description: String(f.description || ''), default: 'main',
        created: nowISO(), updated: nowISO(), creator: u.id
      };
      list('repos').push(repo);
      list('branches').push({ id: uid('b'), repo: repo.id, name: 'main', head: null, created: nowISO() });
      if (f.readme) {
        list('files').push({ id: uid('f'), repo: repo.id, branch: 'main', path: 'README.md', content: '# ' + name + '\n' });
        list('commits').push({
          id: uid('c'), repo: repo.id, branch: 'main', message: 'Initial commit', author: u.id,
          time: nowISO(), parent: null, changes: [{ path: 'README.md', additions: 1, deletions: 0 }]
        });
      }
      ui().errors = {};
      ui().repoValues = {};
      ARC.save();
      ARC.navigate(repoHref(repo));
      ARC.notify('Repository created');
