        return '<div role="option" class="opt" data-action="pick-branch" data-value="' + esc(n) + '">' + esc(n) + '</div>';
      }).join('');
      if (q && names.indexOf(q) < 0) {
        html = '<p>No matching branch</p>' + html;
        if (validBranch(q)) {
          html += '<div role="option" class="opt" data-action="create-branch" data-value="' + esc(q) + '">Create branch: ' + esc(q) + '</div>';
        } else {
          html += '<p>Invalid branch</p>';
