function ownerNameOf(repo) {
    if (!repo) return '';
    var owner = repo.ownerType === 'org' ? orgById(repo.owner) : userById(repo.owner);
    if (!owner) return '';
    if (repo.ownerType === 'org') return owner.name;
    return owner.username || owner.name || '';
  }

function repoByPath(slugOrUser, name) {
    return list('repos').find(function (r) {
      var owner = r.ownerType === 'org' ? orgById(r.owner) : userById(r.owner);
      if (!owner) return false;
      var key = r.ownerType === 'org' ? owner.slug : owner.username;
      return key === slugOrUser && r.name === name;
    }) || null;
  }

function branchOf(repoId, name) {
    return list('branches').find(function (b) { return b.repo === repoId && b.name === name; }) || null;
  }

function filesOn(repoId, branch) {
    return list('files').filter(function (f) { return f.repo === repoId && f.branch === branch; });
  }

function commitsOn(repoId, branch) {
    return list('commits').filter(function (c) { return c.repo === repoId && c.branch === branch; });
  }

function currentBranch(repo) {
    var u = ui();
    var b = u.branch && u.branch[repo.id];
    if (b && branchOf(repo.id, b)) return b;
    return repo.default;
  }

function setCurrentBranch(repo, name) {
    var u = ui();
    u.branch = u.branch || {};
    u.branch[repo.id] = name;
  }

function timeAgo(iso) {
    var t = Date.parse(iso);
    if (!t) return '';
    var s = Math.max(1, Math.floor((Date.now() - t) / 1000));
    if (s < 60) return s + ' seconds ago';
    var m = Math.floor(s / 60);
    if (m < 60) return m + ' minutes ago';
    var h = Math.floor(m / 60);
    if (h < 24) return h + ' hours ago';
    var d = Math.floor(h / 24);
    if (d < 30) return d + ' days ago';
    var mo = Math.floor(d / 30);
    if (mo < 12) return mo + ' months ago';
    return Math.floor(mo / 12) + ' years ago';
  }

function list(k) {
    if (!Array.isArray(ARC.state[k])) ARC.state[k] = [];
    return ARC.state[k];
  }

