        esc(i.status === 'open' ? 'Open' : 'Closed') + '</span></p>' +
        (writable ? '<p><button type="button" data-action="edit-title-open">Edit issue title</button> ' +
          '<button type="button" data-action="edit-desc-open">Edit issue description</button></p>' : '') +
        '<p>' + esc(i.body) + '</p>' +
        '<h2>Assignees</h2><p>' + (assignees || 'No one assigned') + '</p>' +
        (triage ? '<p><button type="button" data-action="assignee-menu">Assignees</button></p>' + (pick === 'assignees' ? this.assigneePicker() : '') : '') +
        '<h2>Labels</h2><p>' + (labels || 'None yet') + '</p>' +
        (triage ? '<p><button type="button" data-action="label-menu">Labels</button></p>' : '') +
        '<h2>Milestone</h2><p>' + esc(ms || 'No milestone') + '</p>' +
        (triage ? '<p><button type="button" data-action="milestone-menu">Milestone</button></p>' + (pick === 'milestone' ? this.milestonePicker(repo, i) : '') : '') +
        (triage ? '<p><button type="button" data-action="toggle-issue">' + (i.status === 'open' ? 'Close issue' : 'Reopen issue') + '</button></p>' : '') +
        '<h2>Activity</h2>' + (acts || '<p>No activity yet.</p>') +
        '<h2>Comments</h2>' + (comments || '<p>No comments yet.</p>') +
        (writable ? '<form data-action="add-comment">' + this.errorBox('comment') +
          this.textarea('Comment', 'body', '') +
          '<button type="submit">Comment</button></form>' : '');
    },
    reactionCount: function (target, id) {
      var rs = list('reactions').filter(function (r) { return r.target === target && r.id === id; });
      return rs.length ? '<span class="meta">' + esc(rs.map(function (r) { return r.type; }).join(' ')) + '</span>' : '';
    },

    /* ---------------------------------------------------------------- pull requests */
    pullListScreen: function (repo) {
      var f = ui().prFilter || {};
      var status = f.status || 'all';
      var author = f.author || '';
      var rows = list('pulls').filter(function (p) { return p.repo === repo.id; }).filter(function (p) {
        if (status !== 'all' && p.status !== status) return false;
        if (author) {
          var a = userById(p.author);
          var name = a ? a.username : '';
          if (name.toLowerCase().indexOf(String(author).toLowerCase()) < 0) return false;
        }
        return true;
      }).map(function (p) { return this.pullRow(p); }, this).join('');
      return this.repoHeader(repo) + '<h2>Pull requests</h2>' +
        '<p><a href="#" data-action="pr-status" data-value="open">Open</a> ' +
        '<a href="#" data-action="pr-status" data-value="closed">Closed</a> ' +
        '<a href="#" data-action="pr-status" data-value="draft">Draft</a> ' +
        '<a href="#" data-action="pr-status" data-value="merged">Merged</a></p>' +
        '<p><input type="text" aria-label="Author" placeholder="Author" data-change="pr-author" value="' + esc(author) + '"></p>' +
        (this.canWrite(repo, this.cur()) ? '<p><a href="' + repoHref(repo) + '/compare">New pull request</a></p>' : '') +
        '<div id="pr-rows">' + (rows || '<p>No pull requests match.</p>') + '</div>';
    },
    pullRow: function (p) {
      var repo = repoById(p.repo);
      var a = userById(p.author);
      var st = { open: 'Open', closed: 'Closed', draft: 'Draft', merged: 'Merged' }[p.status] || 'Open';
      return '<article class="card" data-pull="' + esc(p.id) + '">' +
        '<h3><a href="' + repoHref(repo) + '/pulls/' + p.number + '">' + esc(p.number) + '</a> ' +
        '<a href="' + repoHref(repo) + '/pulls/' + p.number + '">' + esc(p.title) + '</a></h3>' +
        '<p class="meta"><span title="' + esc(st) + '">' + esc(st) + '</span> · ' + esc(a ? a.username : '') + '</p>' +
        '<p class="meta"><span>' + esc(p.base) + '</span> ← <span>' + esc(p.compare) + '</span></p></article>';
    },
    pullHeader: function (repo, pr) {
      var st = { open: 'Open', closed: 'Closed', draft: 'Draft', merged: 'Merged' }[pr.status] || 'Open';
      var base = repoHref(repo) + '/pulls/' + pr.number;
      return '<h1>' + esc(pr.title) + '</h1>' +
        '<p class="meta">#' + pr.number + ' · <span title="' + esc(st) + '">' + esc(st) + '</span></p>' +
        '<p class="meta"><span>' + esc(pr.base) + '</span> ← <span>' + esc(pr.compare) + '</span></p>' +
        '<nav class="subtabs">' +
        '<a href="' + base + '">Conversation</a> ' +
        '<a href="' + base + '/commits">Commits</a> ' +
        '<a href="' + base + '/files">Files changed</a> ' +
        '<a href="' + base + '/checks">Checks</a></nav>';
    },
    pullDetailScreen: function (repo, number, tab) {
      var pr = list('pulls').find(function (p) { return p.repo === repo.id && p.number === number; });
      if (!pr) return this.notFound();
      var body;
      if (tab === 'commits') body = this.pullCommits(repo, pr);
      else if (tab === 'files') body = this.pullFiles(repo, pr);
      else if (tab === 'checks') body = '<h2>Checks</h2>';
      else body = this.pullConversation(repo, pr);
      return this.repoHeader(repo, pr.compare, true) + this.pullHeader(repo, pr) + this.pullSidebar(repo, pr) + body;
    },
    pullConversation: function (repo, pr) {
      var self = this;
      var u = this.cur();
      var comments = list('prComments').filter(function (c) { return c.pr === pr.id; }).map(function (c) {
        var a = userById(c.author);
        return '<article class="card"><h3>' + esc(a ? a.username : '') + '</h3><p>' + esc(c.body) + '</p>' +
          '<p class="meta">' + esc(timeAgo(c.created)) + '</p></article>';
      }).join('');
      var revs = list('reviews').filter(function (r) { return r.pr === pr.id; }).map(function (r) {
        var a = userById(r.reviewer);
        return '<article class="card"><h3>' + esc(a ? a.username : '') + '</h3><p>' + esc(r.state) + '</p>' +
          '<p>' + esc(r.summary || '') + '</p><p class="meta">' + esc(timeAgo(r.time)) + '</p></article>';
      }).join('');
      return '<p>' + esc(pr.body) + '</p>' +
        '<h2>Conversation</h2>' + (comments || '<p>No comments yet.</p>') +
        '<h2>Reviews</h2>' + (revs || '<p>No reviews yet.</p>');
    },
    pullCommits: function (repo, pr) {
      var cs = commitsOn(repo.id, pr.compare).slice().sort(function (a, b) { return Date.parse(b.time) - Date.parse(a.time); });
      return '<h2>Commits</h2><p class="meta">Commit summary</p><p>' + cs.length + ' comparable commits</p>' +
        cs.map(function (c) {
          return '<article class="card"><h3><a href="' + repoHref(repo) + '/commit/' + encodeURIComponent(c.id) + '">' + esc(c.message) + '</a></h3>' +
            '<p class="meta">' + esc(timeAgo(c.time)) + '</p></article>';
        }).join('');
    },
    pullFiles: function (repo, pr) {
      var u = this.cur();
      var canReview = this.canWrite(repo, u) && u && pr.author !== u.id && pr.status === 'open';
      var diff = pr.diff || [];
      var add = diff.reduce(function (n, d) { return n + d.additions; }, 0);
      var del = diff.reduce(function (n, d) { return n + d.deletions; }, 0);
      var editor = ui().lineEditor;
      var blocks = diff.map(function (d) {
        var lines = '';
        if (!editor) {
          for (var i = 1; i <= d.additions + d.deletions && i <= 6; i++) {
            lines += '<div class="diff-line"><button type="button" data-action="line-comment" data-path="' + esc(d.path) + '" data-line="' + i + '" aria-label="Add comment">+</button>' +
              '<span class="meta">' + (i <= d.additions ? '+' : '-') + ' line ' + i + '</span></div>';
          }
        }
        var editorHtml = editor && editor.path === d.path ? APP.inlineEditorHtml() : '';
        return '<article class="card"><h3>' + esc(d.path) + '</h3><p class="meta">+' + d.additions + ' −' + d.deletions + '</p>' + lines + editorHtml + '</article>';
      }).join('');
      var inline = list('inline').filter(function (c) { return c.pr === pr.id; }).map(function (c) {
        var a = userById(c.author);
        return '<article class="card"><h3>' + esc(a ? a.username : '') + '</h3><p>' + esc(c.body) + '</p>' +
          '<p class="meta">' + esc(c.path) + ' line ' + c.line + '</p>' +
          (c.published ? '' : '<p>Pending review</p>') + '</article>';
      }).join('');
      return '<h2>Files changed</h2>' +
        '<p>Changed files</p>' +
        '<p>' + add + ' additions, ' + del + ' deletions</p>' +
        (canReview ? '<p><button type="button" data-action="review-open">Review changes</button></p>' : '') +
        blocks + '<h2>Review comments</h2>' + (inline || '<p>No review comments.</p>');
    },
    pullChecks: function (repo, pr) {
      var u = this.cur();
      var canAdmin = this.canAdmin(repo, u);
      var ck = list('checks').filter(function (c) { return c.pr === pr.id && c.commit === pr.compareCommit; })[0] ||
        list('checks').filter(function (c) { return c.pr === pr.id; })[0];
      var status = ck ? ck.status : 'pending';
      var setter = ck && ck.setter ? userById(ck.setter) : null;
      return '<h2>Checks</h2>' +
        '<p>test: ' + esc(status) + '</p>' +
        (setter ? '<p class="meta">Set by ' + esc(setter.username) + ' ' + esc(ck.time ? timeAgo(ck.time) : '') + '</p>' : '') +
        (canAdmin ? ARC.combobox({ label: 'test status', name: 'testStatus', options: ['pending', 'success', 'failure'], value: ui().checkDraft || status, change: 'check-status' }) +
          '<p><button type="button" data-action="save-check">Save</button></p>' : '');
    },
    pullSidebar: function (repo, pr) {
      var u = this.cur();
      var self = this;
      var canManage = this.canWrite(repo, u) && !!(u && (pr.author === u.id || rank(this.roleOn(repo, u)) >= 4));
      var reqs = list('reviewers').filter(function (r) { return r.pr === pr.id; }).map(function (r) {
        var a = userById(r.user);
        var name = a ? a.username : r.user;
        return '<span class="reviewer">' + esc(name) + '</span> ' +
          (canManage ? '<button type="button" data-action="remove-reviewer" data-id="' + esc(r.user) + '">Remove ' + esc(name) + '</button>' : '');
      }).join(' ');
      var prot = list('protections').find(function (p) { return p.repo === repo.id && p.branch === pr.base; });
      var ck = list('checks').filter(function (c) { return c.pr === pr.id && c.commit === pr.compareCommit; })[0];
      var approved = list('reviews').filter(function (r) {
        return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Approved' && r.reviewer !== pr.author;
      }).length;
      var changes = list('reviews').filter(function (r) {
        return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Changes requested';
      }).length;
      var ok = pr.status === 'open' && (!prot || !prot.approval || approved >= 1);
      var canMerge = rank(this.roleOn(repo, u)) >= 4;
      var mergeArea = '<h2>Merge</h2><p>Create a merge commit</p>' +
        (pr.status === 'merged' ? '<p>Merged</p>' : '') +
        (pr.status === 'closed' ? '<p>This pull request is closed.</p>' : '') +
        (pr.status === 'draft' ? '<p>Draft</p>' : '') +
        ((pr.status === 'open' || pr.status === 'draft') && canMerge
          ? (ok ? '<p><button type="button" data-action="merge-pr">Merge pull request</button></p>'
            : '<p><button type="button" disabled>Merge pull request</button></p>' + (changes || (prot && prot.approval && approved < 1)
              ? '<p>Review required by branch protection</p>' : '<p>This pull request cannot be merged yet.</p>'))
          : '') +
        (pr.status === 'open' || pr.status === 'draft' ? '' : '');
      var statusCtl = '';
      if (u && (pr.author === u.id || rank(this.roleOn(repo, u)) >= 4)) {
        if (pr.status === 'draft') statusCtl = '<p><button type="button" data-action="ready-for-review">Ready for review</button></p>';
        if (pr.status === 'open' || pr.status === 'draft') statusCtl += '<p><button type="button" data-action="close-pr">Close pull request</button></p>';
        else if (pr.status === 'closed') statusCtl = '<p><button type="button" data-action="reopen-pr">Reopen pull request</button></p>';
      }
      var canAdmin = rank(this.roleOn(repo, u)) >= 5;
      var checkHtml = '<h2>Checks</h2><p class="meta">test: ' + esc(ck ? ck.status : 'pending') + '</p>' +
        (ck && ck.setter ? '<p class="meta">Set by ' + esc((userById(ck.setter) || {}).username || '') + '</p>' : '') +
        (canAdmin
          ? '<p class="field"><label for="in-test-status">test status</label>' +
            '<select id="in-test-status" name="testStatus">' +
            ['pending', 'success', 'failure'].map(function (s) {
              return '<option value="' + s + '"' + ((ck ? ck.status : 'pending') === s ? ' selected' : '') + '>' + s + '</option>';
            }).join('') +
            '</select></p><p><button type="button" data-action="save-check">Save</button></p>'
          : '');
      var reviewHtml = list('reviews').filter(function (rv) { return rv.pr === pr.id; }).map(function (rv) {
        var ra = userById(rv.reviewer);
        return '<article class="card"><h3>' + esc(ra ? ra.username : '') + '</h3><p>' + esc(rv.state) + '</p>' +
          (rv.summary ? '<p>' + esc(rv.summary) + '</p>' : '') + '</article>';
      }).join('');
      return '<h2>Reviewers</h2>' +
        (canManage ? '<p><button type="button" data-action="reviewers-menu">Reviewers</button></p>' : '') +
        '<p>' + (reqs || 'No reviewers requested.') + '</p>' +
        '<h2>Reviews</h2>' + (reviewHtml || '<p>No reviews yet.</p>') +
        checkHtml + mergeArea + statusCtl;
    },

    /* ---------------------------------------------------------------- search */
    searchScreen: function () {
      var u = ui();
      var q = u.search || '';
      var type = u.searchType || 'repositories';
      var repo = u.searchRepo ? repoById(u.searchRepo) : null;
      var pathFilter = u.searchPath || '';
      var head = '<h1>Search</h1>' +
        '<p><a href="#" data-action="search-type" data-type="repositories">Repositories</a> ' +
        '<a href="#" data-action="search-type" data-type="code">Code</a></p>';
      if (repo) head += '<p class="meta">' + esc(repo.name) + '</p>';
      var body;
      if (type === 'code') {
        if (!repo) {
          body = '<p>No code results</p>';
        } else {
          var matches = filesOn(repo.id, repo.default).filter(function (f) {
            if (!q) return false;
            if (f.content.toLowerCase().indexOf(String(q).toLowerCase()) < 0) return false;
            if (pathFilter && f.path.indexOf(pathFilter) !== 0) return false;
            return true;
          });
          body = '<p><input type="text" aria-label="Path" placeholder="Path" data-change="search-path" value="' + esc(pathFilter) + '"></p>' +
            '<div id="search-rows">' + (matches.length
              ? matches.map(function (f) {
                var idx = f.content.toLowerCase().indexOf(String(q).toLowerCase());
                var snippet = f.content.slice(Math.max(0, idx - 20), idx + String(q).length + 20);
                return '<article class="card"><h3><a href="' + repoHref(repo, 'code/' + encodeURIComponent(f.branch) + '/' + f.path.split('/').map(encodeURIComponent).join('/')) + '">' +
                  esc(f.path) + '</a></h3><p class="meta">Branch ' + esc(f.branch) + '</p><p><code>' + esc(snippet) + '</code></p></article>';
              }).join('')
              : '<p>No code results</p>') + '</div>';
        }
        return head + body;
      }
      var repos = this.readRepos(this.cur()).filter(function (r) {
        return q && r.name.toLowerCase().indexOf(String(q).toLowerCase()) >= 0;
      });
      var rows = repos.map(function (r) {
        var vis = r.visibility === 'public' ? 'Public' : 'Private';
        return '<article class="card"><h3><a href="' + repoHref(r) + '">' + esc(r.name) + '</a></h3>' +
          '<p class="meta">' + esc(ownerNameOf(r) + '/' + r.name) + '</p>' +
          '<p class="meta"><span title="' + esc(vis) + '">' + esc(vis) + '</span> · updated ' + esc(timeAgo(r.updated)) + '</p>' +
          '<p>' + esc(r.description) + '</p></article>';
      }).join('');
      return head + '<div id="search-rows">' + (rows || '<p>No results</p>') + '</div>';
    },
    searchRows: function () {
      var u = ui();
      var q = u.search || '';
      var repos = this.readRepos(this.cur()).filter(function (r) {
        return q && r.name.toLowerCase().indexOf(String(q).toLowerCase()) >= 0;
      });
      var rows = repos.map(function (r) {
        return '<article class="card"><h3><a href="' + repoHref(r) + '">' + esc(r.name) + '</a></h3>' +
          '<p class="meta">' + esc(ownerNameOf(r) + '/' + r.name) + '</p>' +
          '<p class="meta">' + esc(r.visibility === 'public' ? 'Public' : 'Private') + ' · updated ' + esc(timeAgo(r.updated)) + '</p>' +
          '<p>' + esc(r.description) + '</p></article>';
      }).join('');
      return rows || '<p>No results</p>';
    },

    /* ---------------------------------------------------------------- repo creation / fork */
    newRepoScreen: function () {
      var u = this.cur();
      if (!u) return '<h1>New repository</h1>' + this.denied();
      var owners = [{ id: u.id, name: u.username, type: 'user' }];
      var self = this;
      list('orgs').filter(function (o) { return self.isOrgOwner(o.id, u); }).forEach(function (o) {
        owners.push({ id: o.id, name: o.name, type: 'org' });
