      var username = String(f.username || '').trim();
      var email = String(f.email || '').trim();
      var pw = String(f.password || '');
      var cf = String(f.confirm || '');
      if (!/^[a-z0-9](?:[a-z0-9-]{0,37}[a-z0-9])?$/.test(username) || username.length > 39 || username.indexOf('--') >= 0) {
        errors.username = 'Username format is invalid';
