      var at = email.split('@');
      var emailOk = email.length > 0 && email.length <= 254 && at.length === 2 &&
        at[0].length > 0 && at[1].indexOf('.') > 0 && at[1].split('.').every(function (p) { return p.length > 0; });
      if (!emailOk) errors.email = 'Email format is invalid';
      var pwOk = pw.length >= 12 && pw.length <= 128 && /[A-Z]/.test(pw) && /[a-z]/.test(pw) && /[0-9]/.test(pw) &&
        /[^A-Za-z0-9]/.test(pw) && !/\s/.test(pw);
      if (!pwOk) errors.password = 'Password requirements are not satisfied';
      else if (cf !== pw) errors.confirm = 'Passwords do not match';
      if (!f.terms) errors.terms = 'Agree to terms is required';
      ui().signupValues = { username: username, email: email };
      ui().errors = errors;
      if (Object.keys(errors).length) {
        ARC.render();
        return;
      }
      list('users').push({
        id: uid('u'), username: username, email: email, password: pw, verified: true, created: nowISO()
