    'create-fork': function (ctx) {
      var r = ARC.route();
      var repo = repoByPath(r.params[0], r.params[1]);
      var u = ARC.currentUser();
      var name = String((ctx.form && ctx.form.name) || '').trim();
      if (!name) { ui().errors = { name: 'Repository name is required' }; ARC.closeDialog(); ARC.render(); return; }
      if (list('repos').some(function (x) { return x.owner === u.id && x.name === name; })) {
        ARC.notify('Repository name already exists');
        return;
      }
      var fork = {
        id: uid('r'), name: name, owner: u.id, ownerType: 'user',
        visibility: repo.visibility === 'private' ? 'private' : 'public',
        description: 'Fork of ' + repo.name, default: 'main', forkOf: repo.id,
        created: nowISO(), updated: nowISO()
      };
      list('repos').push(fork);
      var sourceBranches = list('branches').filter(function (b) { return b.repo === repo.id; });
      sourceBranches.forEach(function (b) {
        list('branches').push({ id: uid('b'), repo: fork.id, name: b.name, head: b.head, created: nowISO() });
        filesOn(repo.id, b.name).forEach(function (f) {
          list('files').push({ id: uid('f'), repo: fork.id, branch: b.name, path: f.path, content: f.content });
        });
        commitsOn(repo.id, b.name).forEach(function (c) {
          list('commits').push({
            id: uid('c'), repo: fork.id, branch: b.name, message: c.message, author: c.author,
            time: c.time, parent: c.parent, changes: c.changes
          });
        });
      });
      ui().errors = {};
      ARC.save();
      ARC.closeDialog();
      ARC.navigate(repoHref(fork));
    },
