    'create-rule': function (ctx) {
      var r = ARC.route();
      var repo = repoByPath(r.params[0], r.params[1]);
      var f = ctx.form || {};
      var branch = String(f.branch || '').trim();
      if (!branch) { ARC.notify('Branch name is required'); return; }
      var existing = list('protections').find(function (p) { return p.repo === repo.id && p.branch === branch; });
      if (existing) {
        existing.approval = !!f.approval;
