      ARC.openDialog('<form data-action="commit-file" data-branch="' + esc(branch) + '" data-path="' + esc(path) + '">' +
        '<p class="field"><label for="in-filename">File name</label><input id="in-filename" name="filename" value="' + esc(path) + '"></p>' +
