    'commit-file': function (ctx) {
      var r = ARC.route();
      var repo = repoByPath(r.params[0], r.params[1]);
      var branch = ctx.el.dataset.branch;
      var editing = ctx.el.dataset.path;
      var f = ctx.form || {};
      var path = String(f.filename || '').trim() || editing;
      var message = String(f.message || '').trim();
      var contents = String(f.contents || '');
      if (!path || path.charAt(0) === '/' || path.indexOf('..') >= 0) { ARC.notify('Invalid file path'); return; }
      if (!message) { ARC.notify('Commit message is required'); return; }
      if (!editing && filesOn(repo.id, branch).some(function (x) { return x.path === path; })) { ARC.notify('Invalid file path'); return; }
      var existing = filesOn(repo.id, branch).find(function (x) { return x.path === path; });
      if (existing) existing.content = contents;
      else list('files').push({ id: uid('f'), repo: repo.id, branch: branch, path: path, content: contents });
      var u = ARC.currentUser();
      var head = branchOf(repo.id, branch);
      list('commits').push({
        id: uid('c'), repo: repo.id, branch: branch, message: message, author: u ? u.id : 'u-alice',
        time: nowISO(), parent: head ? head.head : null,
        changes: [{ path: path, additions: contents.split('\n').length - 1, deletions: existing ? 1 : 0 }]
      });
      ARC.save();
      ARC.closeDialog();
      ARC.navigate(repoHref(repo, 'code/' + encodeURIComponent(branch) + '/' + path.split('/').map(encodeURIComponent).join('/')));
      ARC.notify('File committed');
    },

