      var issue = {
        id: uid('i'), repo: repo.id, number: number, title: title,
        body: String((ctx.form && ctx.form.body) || ''), author: u.id, status: 'open',
        labels: [], milestone: null, assignees: [], created: nowISO(), updated: nowISO()
      };
      list('issues').push(issue);
      list('activities').push({ id: uid('a'), kind: 'issue', subject: issue.id, text: 'opened the issue', actor: u.id, created: nowISO() });
      ARC.save();
      ARC.navigate(repoHref(repo, 'issues/' + number));
      ARC.notify('Issue created');
